sys_script_client.script:
function onLoad() {
    // MSSCUSTODY 6260 - Client Script created to show only those values in Bulk Field Group Dropdown which are having at least one editable field

    //to restrict evaluation only for amend
    var evalBulk = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    evalBulk.addParam('sysparm_name', 'checkIfOutcomeHoldsAmend');
    evalBulk.addParam('sysparm_bulkID', g_form.getUniqueValue());
    evalBulk.getXMLAnswer(amendEval);
    //to restrict evaluation only for amend


    function amendEval(amendAnswer) {
        if (amendAnswer == 'true') { //atleast one of the bulk outcome has amend 
            var bulkID = g_form.getUniqueValue(); // Get the current record's sys_id
            var glideAjax = new GlideAjax('x_hsb11_hsbc_mss_o.MSSAmendUtilsCore');
            glideAjax.addParam('sysparm_name', 'fetchEligibleFieldsForBulkAmend');
            glideAjax.addParam('sysparm_bulkid', bulkID); // Pass bulk ID as a parameter
            glideAjax.getXMLAnswer(getAnswer);
        }
    }

    function getAnswer(response) {
        var result = JSON.parse(response); // Parse the JSON response
        var hiddenFields = result.hiddenFields;
        var nonEditableFields = result.nonEditableFields;
        var combinedFields = hiddenFields.concat(nonEditableFields); // Combine hidden and non-editable fields

        // Mapping of bulk field groups to their respective fields
        var bulkFieldGroups = {
            'customer_reference': ['customer_reference'],
            'trade_settl_date': ['amend_trade_date', 'settlement_date', 'amend_swh'], // MSSCUSTODY-7898
            'cash_hold_indicator': ['amend_cash_hold_indicator'],
            'beneficiary_details': [
                'amend_a_c_of_client',
                'amend_deliverer_custodian_bic_receiver_custodian_bic',
                'amend_seller_bic_buyer_bic',
                'amend_place_of_settlement_bic',
				'amend_receiver_custodian_bic', // MSSCUSTODY-7159 - Added Receiver Custodian (BIC)
				'amend_buyer_bic', // MSSCUSTODY-7159 - Added Buyer (BIC)
            ],
            'counterparty_details': [
                'counterparty_reference',
                'amend_payment_method',
                'amend_counterparty_code',
                'amend_counterparty_settlement_account_number',
                'amend_counterparty_code_ref'
            ],
            'location_gdi': ['amend_location_code', 'amend_gdi_indicator'],
            'hmi_indicator': ['amend_hmi_indicator'],
            'script_hold_indicator': ['amend_script_hold_indicator'],
            'security_id': ['security_id_sec_id', 'amend_security_id_sec_id_ref'],
            'amendment_charges': ['amend_charges_ccy', 'amend_charges_amt', 'amend_charges_type'],
			'blank_trade_date' : [],
			'fa': ['amend_fa'],
			'iss': ['amend_iss']
        };

        // Iterate through bulk field groups and remove dropdown values if all fields are hidden or non-editable
        for (var group in bulkFieldGroups) {
            var fields = bulkFieldGroups[group];
            var allFieldsHiddenOrNonEditable = fields.every(function(field) {
                return combinedFields.includes(field); // Check if all fields in the group are hidden or non-editable
            });

            if (allFieldsHiddenOrNonEditable) {
                var dropdown = g_form.getControl('bulk_field_group'); // Get the dropdown control
                if (dropdown) {
                    var options = dropdown.options;
                    for (var i = 0; i < options.length; i++) {
                        if (options[i].value === group && group != 'blank_trade_date') {
                            dropdown.remove(i); // Remove the option from the dropdown 
                            break;
                        }
                    }
                }
            }
        }
    }
}
